// Where the Post button lives. Empty url means stay on this page.
// Navigation is a separate step: doing it inside the post eval drops the realm.
(async () => {
  const ARGS = {{args_json}};
  const reply = ARGS && ARGS.reply_to ? String(ARGS.reply_to).trim() : "";
  const href = String(location.href || "");
  function planUrl(page, replyTo) {
    if (replyTo) {
      if (!/^\d+$/.test(replyTo)) return "";
      if (page.indexOf("/status/" + replyTo) >= 0 || page.indexOf("in_reply_to=" + replyTo) >= 0) return "";
      return "https://x.com/i/status/" + replyTo;
    }
    const onHome = /\/\/(?:x|twitter)\.com\/home\/?(?:$|[?#])/.test(page);
    const onCompose = page.indexOf("/compose/post") >= 0 && page.indexOf("in_reply_to=") < 0;
    if (onHome || onCompose) return "";
    return "https://x.com/home";
  }
  return { url: planUrl(href, reply), reply_to: reply, from: href };
})()

// Click the composer Post button. Direct CreateTweet is not used:
// on 2026-10-22 a URL tweet returned 344 from that call, and this button published it.
// /posted/ in the page text is not success — home already contains that word.

(async () => {
  const ARGS = {{args_json}};
  const text = ARGS && ARGS.text ? String(ARGS.text) : "";
  const reply = ARGS && ARGS.reply_to ? String(ARGS.reply_to).trim() : "";
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const flat = (s) => String(s || "").replace(/\s+/g, " ").trim();

  function out(extra) {
    return JSON.stringify(Object.assign({
      ok: false,
      status: null,
      tweet_id: null,
      text_head: text.slice(0, 60),
      err_code: null,
      err_msg: null,
      via: "post_button",
      confirmed: null,
      href: location.href,
      n_feat: 0,
      n_tog: 0,
      features_err: null
    }, extra || {}));
  }

  async function storeFeatures() {
    try {
      const src = [...document.querySelectorAll("script[src*='main']")].map((s) => s.src)[0];
      if (!src) return { features_err: "no main.js" };
      const bundle = await (await fetch(src, { credentials: "omit" })).text();
      let at = bundle.indexOf('operationName:"CreateTweet"');
      if (at < 0) at = bundle.indexOf("operationName:'CreateTweet'");
      if (at < 0) return { features_err: "CreateTweet metadata missing from main.js" };
      const meta = bundle.indexOf("featureSwitches:", at);
      if (meta < 0) return { features_err: "featureSwitches missing" };
      const start = bundle.indexOf("[", meta);
      const end = bundle.indexOf("]", start);
      const featNames = JSON.parse(bundle.slice(start, end + 1));
      if (!Array.isArray(featNames) || !featNames.length) return { features_err: "featureSwitches empty" };
      const features = {};
      for (const n of featNames) features[n] = true;
      const fieldToggles = {};
      const ft = bundle.indexOf("fieldToggles:", at);
      if (ft > 0 && ft < at + 8000) {
        const s2 = bundle.indexOf("[", ft);
        const e2 = bundle.indexOf("]", s2);
        const togNames = JSON.parse(bundle.slice(s2, e2 + 1));
        for (const n of togNames) fieldToggles[n] = true;
      }
      localStorage.setItem("abx_ct_features", JSON.stringify(features));
      localStorage.setItem("abx_ct_toggles", JSON.stringify(fieldToggles));
      return { n_feat: featNames.length, n_tog: Object.keys(fieldToggles).length, features_err: null };
    } catch (e) {
      return { features_err: e.name + ": " + e.message };
    }
  }

  function alertText() {
    const nodes = document.querySelectorAll('[role="alert"], [data-testid="toast"]');
    const parts = [];
    for (const n of nodes) {
      const t = (n.innerText || "").trim();
      if (t) parts.push(t);
    }
    return parts.join(" ").slice(0, 180);
  }

  function fill(box, value) {
    const fk = Object.keys(box).find((k) => k.indexOf("__reactFiber") === 0);
    if (!fk) return "composer has no react fiber";
    let fiber = box[fk];
    let editor = null;
    while (fiber) {
      const sn = fiber.stateNode;
      if (sn && sn.props && sn.props.editorState && sn.props.onChange && sn.props.handlePastedText) {
        editor = sn;
        break;
      }
      fiber = fiber.return;
    }
    if (!editor) return "draft editor not found";
    const es = editor.props.editorState;
    const ContentState = es.getCurrentContent().constructor;
    const EditorState = es.constructor;
    editor.props.onChange(EditorState.createWithContent(ContentState.createFromText(value)));
    return "";
  }

  function inDialog(el) {
    let n = el;
    while (n) {
      if (n.getAttribute && n.getAttribute("role") === "dialog") return true;
      n = n.parentElement;
    }
    return false;
  }

  function buttonNear(box) {
    let n = box;
    for (let i = 0; i < 14 && n; i++) {
      const inline = n.querySelector('[data-testid="tweetButtonInline"]');
      const modal = n.querySelector('[data-testid="tweetButton"]');
      if (inline && !inDialog(inline)) return inline;
      if (modal) return modal;
      if (inline) return inline;
      n = n.parentElement;
    }
    return document.querySelector('[data-testid="tweetButtonInline"]') || document.querySelector('[data-testid="tweetButton"]');
  }

  function disabled(btn) {
    return !btn || btn.getAttribute("aria-disabled") === "true" || btn.hasAttribute("disabled");
  }

  function knownIds() {
    const ids = [];
    const arts = document.querySelectorAll("article");
    for (const a of arts) {
      const link = a.querySelector('a[href*="/status/"]');
      const href = link ? (link.href || link.getAttribute("href") || "") : "";
      const m = String(href).match(/status\/(\d+)/);
      if (m) ids.push(m[1]);
    }
    return ids;
  }

  function matchDom(before, want) {
    const needle = want.slice(0, Math.min(12, want.length));
    const arts = document.querySelectorAll("article");
    for (const a of arts) {
      const link = a.querySelector('a[href*="/status/"]');
      const href = link ? (link.href || link.getAttribute("href") || "") : "";
      const m = String(href).match(/status\/(\d+)/);
      if (!m || before.indexOf(m[1]) >= 0) continue;
      const blob = flat(a.innerText);
      if (needle && blob.indexOf(needle) >= 0) return m[1];
    }
    return "";
  }


  try {
    const feat = await storeFeatures();
    if (!flat(text)) return out(Object.assign({ err_msg: "empty text" }, feat));
    if (reply && !/^\d+$/.test(reply)) {
      return out(Object.assign({ err_msg: "reply_to must be a numeric tweet id" }, feat));
    }

    if (reply) {
      const t0 = Date.now();
      while (Date.now() - t0 < 5000) {
        const href = String(location.href || "");
        if (href.indexOf("/status/" + reply) >= 0 || href.indexOf("in_reply_to=" + reply) >= 0) break;
        await sleep(200);
      }
      const href = String(location.href || "");
      if (href.indexOf("/status/" + reply) < 0 && href.indexOf("in_reply_to=" + reply) < 0) {
        return out(Object.assign({
          err_msg: "not on the reply page for " + reply + ". This flow does not call CreateTweet."
        }, feat));
      }
    }

    let box = document.querySelector('[data-testid="tweetTextarea_0"]');
    if (!box && reply) {
      const arts = [...document.querySelectorAll("article")];
      let focal = null;
      for (const a of arts) {
        if ((a.innerHTML || "").indexOf("/status/" + reply) >= 0) { focal = a; break; }
      }
      if (!focal) focal = arts[0] || null;
      const replyBtn = focal && focal.querySelector('[data-testid="reply"]');
      if (replyBtn) replyBtn.click();
    }
    const t1 = Date.now();
    while (!box && Date.now() - t1 < 12000) {
      await sleep(200);
      box = document.querySelector('[data-testid="tweetTextarea_0"]');
    }
    if (!box) {
      return out(Object.assign({
        err_msg: reply
          ? "reply composer did not open"
          : "no composer on this page"
      }, feat));
    }

    const fillErr = fill(box, text);
    if (fillErr) return out(Object.assign({ err_msg: fillErr }, feat));
    await sleep(400);
    const shown = flat(box.innerText);
    const want = flat(text);
    const needle = want.slice(0, Math.min(12, want.length));
    if (needle && shown.indexOf(needle) < 0) {
      return out(Object.assign({ err_msg: "composer did not take the text" }, feat));
    }

    let btn = null;
    const t2 = Date.now();
    while (Date.now() - t2 < 2000) {
      btn = buttonNear(box);
      if (!disabled(btn)) break;
      await sleep(200);
    }
    if (disabled(btn)) {
      return out(Object.assign({ err_msg: "Post stayed disabled" }, feat));
    }

    const before = knownIds();
    btn.click();

    let tweetId = null;
    let errCode = null;
    let errMsg = null;
    let confirmed = null;
    let cleared = false;
    let alertSeen = "";
    // Confirm via DOM only — no window.fetch / XHR wrap (page owns CreateTweet).
    const t3 = Date.now();
    while (Date.now() - t3 < 6000) {
      const domId = matchDom(before, want);
      if (domId) {
        tweetId = domId;
        confirmed = "timeline";
        break;
      }
      const alert = alertText();
      if (alert) alertSeen = alert;
      if (alert && /daily limit|try again later|\(344\)/i.test(alert)) {
        errMsg = alert;
        confirmed = "alert";
        break;
      }
      const live = document.querySelector('[data-testid="tweetTextarea_0"]');
      const len = live ? flat(live.innerText).length : 0;
      if ((!live || len === 0) && Date.now() - t3 > 800) cleared = true;
      await sleep(250);
    }
    if (!confirmed && cleared) confirmed = "composer_cleared";
    const ok = !!(tweetId || (confirmed === "composer_cleared" && !errCode && !errMsg));
    return out(Object.assign({
      ok: ok,
      status: null,
      tweet_id: tweetId,
      err_code: errCode,
      err_msg: ok ? null : (errMsg || alertSeen || "Post was clicked and the composer did not clear"),
      confirmed: confirmed
    }, feat));

  } catch (e) {
    return out({ err_msg: e.name + ": " + e.message });
  }
})()

// x-reply step: verify the reply landed — TweetDetail focal=parent, our uid in thread
(async () => {
  const ARGS = {{args_json}};
  try {
    if (!ARGS.reply_to) return JSON.stringify({ok: true, skipped: true, why: 'root tweet - nothing to verify'});
    await new Promise(res => setTimeout(res, 1500));
    let uid = localStorage.getItem('abx_uid');
    const argUid = '{{uid}}';
    if (!uid && argUid) { uid = argUid; localStorage.setItem('abx_uid', uid); }
    const bearer = localStorage.getItem('abx_bearer');
    const ct0 = (document.cookie.match(/(?:^|;\s*)ct0=([^;]+)/) || [])[1];
    const features = JSON.parse(localStorage.getItem('abx_ct_features'));
    if (!bearer || !ct0 || !features) return JSON.stringify({ok: false, err: 'missing bearer/ct0/features'});
    const variables = {focalTweetId: String(ARGS.reply_to), withRuxInjections: false, includePromotedContent: true,
      withCommunityNoteHydrationEnabled: false, withBirdwatchNotes: false, withVoice: true,
      withSuperFollowsUserFields: false, withDownvotePerspective: false, withReactionsMetadata: false,
      withReactionsPerspective: false, withSuperFollowsTweetFields: false, withBirdwatchPivots: false};
    const q = '/i/api/graphql/FyR-GrebyjdkRoW1z6uCgQ/TweetDetail?variables=' +
      encodeURIComponent(JSON.stringify(variables)) + '&features=' + encodeURIComponent(JSON.stringify(features));
    const r = await fetch(q, {credentials: 'include', headers: {
      'authorization': 'Bearer ' + bearer,
      'x-twitter-auth-type': 'OAuth2Session',
      'x-csrf-token': ct0,
      'x-twitter-client-language': 'en',
      'x-twitter-active-user': 'yes'
    }});
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch {}
    if (!r.ok) return JSON.stringify({ok: false, verified: false, status: r.status, err_head: t.slice(0, 120)});
    const mine = [];
    const pick = (ic) => {
      const res = ic && ic.tweet_results && ic.tweet_results.result;
      const core = res && res.__typename === 'TweetWithVisibilityResults' ? res.tweet : res;
      const u = core && core.core && core.core.user_results && core.core.user_results.result;
      if (uid && u && u.rest_id === uid && core.legacy) mine.push(core.legacy.id_str);
    };
    const walk = (entries) => {
      for (const e of (entries || [])) {
        const c = e && e.content;
        if (!c) continue;
        if (c.itemContent) pick(c.itemContent);
        if (c.items) for (const it of c.items) pick(it.item && it.item.itemContent);
      }
    };
    for (const ins of ((j.data && j.data.threaded_conversation_with_injections_v2 && j.data.threaded_conversation_with_injections_v2.instructions) || [])) walk(ins.entries);
    return JSON.stringify({ok: true, verified: mine.length > 0, mine_in_thread: mine});
  } catch (e) {
    return JSON.stringify({ok: false, verified: false, err: e.name + ': ' + e.message});
  }
})()
